// Ported from Job Intelligence (server/engine/deduplicator.ts)
//
// Portable core module: the original used node:crypto (sha256). To keep core free of
// Node built-ins, a small pure-JS synchronous SHA-256 is included below. It produces the
// same hex digest as crypto.createHash('sha256').update(str).digest('hex'), so content
// hashes remain identical to those generated by the original app.

const SHA256_K = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

function utf8Bytes(str) {
  if (typeof TextEncoder !== 'undefined') {
    return new TextEncoder().encode(str);
  }
  // Fallback for environments without TextEncoder
  const bin = unescape(encodeURIComponent(str));
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function rotr(x, n) {
  return (x >>> n) | (x << (32 - n));
}

function sha256Hex(message) {
  const bytes = utf8Bytes(message);
  const len = bytes.length;
  const paddedLen = ((len + 9 + 63) >> 6) << 6;
  const buf = new Uint8Array(paddedLen);
  buf.set(bytes);
  buf[len] = 0x80;

  const bitLen = len * 8;
  const hi = Math.floor(bitLen / 4294967296) >>> 0;
  const lo = bitLen >>> 0;
  buf[paddedLen - 8] = (hi >>> 24) & 0xff;
  buf[paddedLen - 7] = (hi >>> 16) & 0xff;
  buf[paddedLen - 6] = (hi >>> 8) & 0xff;
  buf[paddedLen - 5] = hi & 0xff;
  buf[paddedLen - 4] = (lo >>> 24) & 0xff;
  buf[paddedLen - 3] = (lo >>> 16) & 0xff;
  buf[paddedLen - 2] = (lo >>> 8) & 0xff;
  buf[paddedLen - 1] = lo & 0xff;

  const H = [
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
    0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
  ];
  const W = new Array(64);

  for (let offset = 0; offset < paddedLen; offset += 64) {
    for (let t = 0; t < 16; t++) {
      const j = offset + t * 4;
      W[t] = ((buf[j] << 24) | (buf[j + 1] << 16) | (buf[j + 2] << 8) | buf[j + 3]) | 0;
    }
    for (let t = 16; t < 64; t++) {
      const w15 = W[t - 15];
      const w2 = W[t - 2];
      const s0 = rotr(w15, 7) ^ rotr(w15, 18) ^ (w15 >>> 3);
      const s1 = rotr(w2, 17) ^ rotr(w2, 19) ^ (w2 >>> 10);
      W[t] = (W[t - 16] + s0 + W[t - 7] + s1) | 0;
    }

    let a = H[0] | 0;
    let b = H[1] | 0;
    let c = H[2] | 0;
    let d = H[3] | 0;
    let e = H[4] | 0;
    let f = H[5] | 0;
    let g = H[6] | 0;
    let h = H[7] | 0;

    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + SHA256_K[t] + W[t]) | 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) | 0;
      h = g;
      g = f;
      f = e;
      e = (d + t1) | 0;
      d = c;
      c = b;
      b = a;
      a = (t1 + t2) | 0;
    }

    H[0] = (H[0] + a) | 0;
    H[1] = (H[1] + b) | 0;
    H[2] = (H[2] + c) | 0;
    H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0;
    H[5] = (H[5] + f) | 0;
    H[6] = (H[6] + g) | 0;
    H[7] = (H[7] + h) | 0;
  }

  let hex = '';
  for (let i = 0; i < 8; i++) {
    hex += (H[i] >>> 0).toString(16).padStart(8, '0');
  }
  return hex;
}

export function normalizeTitle(title) {
  return title
    .toLowerCase()
    .replace(/\b(sr|sr\.|senior|junior|jr|lead|principal|staff)\b/gi, '')
    .replace(/[^a-z0-9\s]/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

export function normalizeCompanyName(company) {
  return company
    .toLowerCase()
    .replace(/\b(inc|incorporated|llc|ltd|limited|corp|corporation|gmbh|co|technologies|solutions|services)\b/gi, '')
    .replace(/[^a-z0-9\s]/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

export function generateContentHash(title, company, description) {
  const norm = `${normalizeTitle(title)}|${normalizeCompanyName(company)}|${description.slice(0, 400).toLowerCase().replace(/\s+/g, ' ')}`;
  return sha256Hex(norm).slice(0, 16);
}

export function isSameJob(raw, existing) {
  // Check 1: Matching external ID and source
  if (raw.external_job_id && existing.external_job_id === raw.external_job_id && raw.source_id === existing.source_id) {
    return true;
  }

  // Check 2: Matching content hash
  const rawHash = generateContentHash(raw.title, raw.company, raw.description);
  if (rawHash === existing.content_hash) {
    return true;
  }

  // Check 3: Normalized title + Normalized company match with location overlap
  const normTitleRaw = normalizeTitle(raw.title);
  const normTitleExist = normalizeTitle(existing.title);
  const normCompanyRaw = normalizeCompanyName(raw.company);
  const normCompanyExist = normalizeCompanyName(existing.company);

  if (normTitleRaw === normTitleExist && normCompanyRaw === normCompanyExist) {
    // Both are same company and role
    return true;
  }

  return false;
}

export function mergeRawIntoJob(raw, existing) {
  const now = new Date().toISOString();
  const changes = [];
  let isNewProvenance = false;

  // Check if this source is already recorded
  const hasSource = existing.all_sources.some(
    (s) => s.source_name.toLowerCase() === raw.source_name.toLowerCase() || s.original_url === raw.original_url
  );

  const updatedSources = [...existing.all_sources];
  if (!hasSource) {
    updatedSources.push({
      source_name: raw.source_name,
      source_type: raw.source_type,
      original_url: raw.original_url,
      external_job_id: raw.external_job_id,
      discovered_at: now,
      last_checked_at: now,
    });
    isNewProvenance = true;
    changes.push({
      timestamp: now,
      type: 'status',
      description: `Cross-listed opportunity discovered on ${raw.source_name}`,
    });
  } else {
    // Update last_checked_at on existing source
    const idx = updatedSources.findIndex((s) => s.source_name.toLowerCase() === raw.source_name.toLowerCase());
    if (idx !== -1) {
      updatedSources[idx].last_checked_at = now;
    }
  }

  // Detect changes:
  // 1. Salary change
  if (raw.salary_min && (!existing.salary_min || existing.salary_min !== raw.salary_min)) {
    changes.push({
      timestamp: now,
      type: 'salary',
      description: `Salary updated to ${raw.salary_raw || `$${raw.salary_min} - $${raw.salary_max}`}`,
    });
  }

  // 2. Status / Repost detection
  let newStatus = existing.status;
  let isRepost = existing.is_repost;
  let prevSeen = existing.previous_seen_date;

  if (existing.status === 'closed' || existing.status === 'expired') {
    newStatus = 'reposted';
    isRepost = true;
    prevSeen = existing.first_seen_at;
    changes.push({
      timestamp: now,
      type: 'repost',
      description: `Role reposted by employer after closure (previously active on ${new Date(existing.first_seen_at).toLocaleDateString()})`,
    });
  }

  // Merge skills
  const mergedSkills = Array.from(new Set([...existing.skills, ...raw.skills]));

  const updatedJob = {
    ...existing,
    all_sources: updatedSources,
    last_seen_at: now,
    last_changed_at: changes.length > 0 ? now : existing.last_changed_at,
    salary_min: raw.salary_min || existing.salary_min,
    salary_max: raw.salary_max || existing.salary_max,
    salary_currency: raw.salary_currency || existing.salary_currency,
    salary_raw: raw.salary_raw || existing.salary_raw,
    skills: mergedSkills,
    status: newStatus,
    is_repost: isRepost,
    previous_seen_date: prevSeen,
    change_history: [...changes, ...existing.change_history],
  };

  // Deliberate change: carry the synthetic flag from raw payloads (search_discovery connector)
  if (raw.synthetic === true) {
    updatedJob.is_synthetic = true;
  }

  return { updatedJob, isNewProvenance, changes };
}

export function convertRawToJob(raw) {
  const now = new Date().toISOString();
  const hash = generateContentHash(raw.title, raw.company, raw.description);
  const jobId = `job-${Date.now()}-${Math.random().toString(36).substring(2, 8)}`;
  const companyId = `comp-${raw.company.toLowerCase().replace(/[^a-z0-9]/g, '-')}`;

  const provenance = {
    source_name: raw.source_name,
    source_type: raw.source_type,
    original_url: raw.original_url,
    external_job_id: raw.external_job_id,
    discovered_at: now,
    last_checked_at: now,
  };

  const initialChange = {
    timestamp: now,
    type: 'created',
    description: `Discovered from ${raw.source_name} (${raw.source_type})`,
  };

  const job = {
    id: jobId,
    external_job_id: raw.external_job_id,
    source_id: raw.source_id,
    source_name: raw.source_name,
    title: raw.title,
    normalized_title: normalizeTitle(raw.title),
    company: raw.company,
    company_id: companyId,
    location: raw.location,
    country: raw.country || 'Global',
    city: raw.city || raw.location.split(',')[0].trim(),
    state: raw.state,
    remote_mode: raw.remote_mode,
    employment_type: raw.employment_type,
    min_experience: raw.min_experience,
    max_experience: raw.max_experience,
    salary_min: raw.salary_min,
    salary_max: raw.salary_max,
    salary_currency: raw.salary_currency,
    salary_raw: raw.salary_raw,
    skills: raw.skills,
    required_skills: raw.required_skills || raw.skills.slice(0, 3),
    preferred_skills: raw.preferred_skills || raw.skills.slice(3),
    description: raw.description,
    summary_30s: raw.summary_30s,
    responsibilities: raw.responsibilities,
    original_url: raw.original_url,
    company_careers_url: raw.company_careers_url,
    first_seen_at: raw.posted_at || now,
    last_seen_at: now,
    last_changed_at: now,
    status: 'active',
    is_repost: false,
    all_sources: [provenance],
    change_history: [initialChange],
    content_hash: hash,
    visa_sponsorship: raw.visa_sponsorship || 'not_specified',
  };

  // Deliberate change: carry the synthetic flag from raw payloads (search_discovery connector)
  if (raw.synthetic === true) {
    job.is_synthetic = true;
  }

  return job;
}
